// Extraer y validar datos del webhook de Pine Script
const body = $input.first().json.body || $input.first().json;

const tipo_zona = body.tipo_zona;
const precio_zona_suelo = parseFloat(body.precio_zona_suelo);
const precio_zona_techo = parseFloat(body.precio_zona_techo);
const direccion_precio = body.direccion_precio;
const precio_actual = parseFloat(body.precio_actual);
const score_1h = parseFloat(body.score_1h || 0);
const score_15m = parseFloat(body.score_15m || 0);
const score_5m = parseFloat(body.score_5m || 0);
const nivel_arriba_tipo = body.nivel_arriba_tipo || null;
const nivel_arriba_precio = body.nivel_arriba_precio ? parseFloat(body.nivel_arriba_precio) : null;
const nivel_abajo_tipo = body.nivel_abajo_tipo || null;
const nivel_abajo_precio = body.nivel_abajo_precio ? parseFloat(body.nivel_abajo_precio) : null;

// Calcular score confluencia ponderado
const score_confluencia = Math.round(score_1h * 0.50 + score_15m * 0.30 + score_5m * 0.20);

// Calcular fase según distancia al precio
const zona_mid = (precio_zona_suelo + precio_zona_techo) / 2;
const distancia_pct = Math.abs(precio_actual - zona_mid) / zona_mid * 100;
let fase = 'LEJOS';
if (precio_actual >= precio_zona_suelo && precio_actual <= precio_zona_techo) {
  fase = 'EN_ZONA';
} else if (distancia_pct < 0.3) {
  fase = 'ACERCANDO';
}

return [{
  json: {
    tipo_zona,
    precio_zona_suelo,
    precio_zona_techo,
    direccion_precio,
    precio_actual,
    score_confluencia,
    fase,
    nivel_arriba_tipo,
    nivel_arriba_precio,
    nivel_abajo_tipo,
    nivel_abajo_precio,
    activo: 'XAUUSD'
  }
}];

// Calcular probabilidades desde historial
const datosFase = $('Parsear y Calcular Fase').first().json;
const historialZona = $('Consultar Historial Zona').first().json;
const historialNiveles = $('Consultar Historial Niveles').first().json;

// Probabilities zona
const registros = Array.isArray(historialZona) ? historialZona : [];
const total = registros.length;

let respeto_fuerte = 0, respeto_debil = 0, rompio = 0, sin_reaccion = 0;
for (const r of registros) {
  if (r.resultado === 'respeto_fuerte') respeto_fuerte++;
  else if (r.resultado === 'respeto_debil') respeto_debil++;
  else if (r.resultado === 'rompio') rompio++;
  else sin_reaccion++;
}

const prob_respeto_fuerte = total > 0 ? parseFloat(((respeto_fuerte / total) * 100).toFixed(2)) : 0;
const prob_respeto_debil = total > 0 ? parseFloat(((respeto_debil / total) * 100).toFixed(2)) : 0;
const prob_rompio = total > 0 ? parseFloat(((rompio / total) * 100).toFixed(2)) : 0;
const muestra_suficiente = total >= 15;

// Probabilidades niveles
const nivelesArr = Array.isArray(historialNiveles) ? historialNiveles : [];

function calcProbNivel(tipo) {
  const del_tipo = nivelesArr.filter(n => n.tipo_nivel === tipo);
  const rotos = del_tipo.filter(n => n.fue_roto).length;
  return { prob: del_tipo.length > 0 ? parseFloat(((rotos / del_tipo.length) * 100).toFixed(2)) : 0, casos: del_tipo.length };
}

const arriba_stats = datosFase.nivel_arriba_tipo ? calcProbNivel(datosFase.nivel_arriba_tipo) : { prob: 0, casos: 0 };
const abajo_stats = datosFase.nivel_abajo_tipo ? calcProbNivel(datosFase.nivel_abajo_tipo) : { prob: 0, casos: 0 };

return [{
  json: {
    activo: 'XAUUSD',
    tipo_zona: datosFase.tipo_zona,
    precio_zona_suelo: datosFase.precio_zona_suelo,
    precio_zona_techo: datosFase.precio_zona_techo,
    direccion_precio: datosFase.direccion_precio,
    prob_respeto_fuerte,
    prob_respeto_debil,
    prob_rompio,
    casos_totales: total,
    muestra_suficiente,
    nivel_arriba_tipo: datosFase.nivel_arriba_tipo,
    nivel_arriba_precio: datosFase.nivel_arriba_precio,
    nivel_arriba_prob_ruptura: arriba_stats.prob,
    nivel_arriba_casos: arriba_stats.casos,
    nivel_abajo_tipo: datosFase.nivel_abajo_tipo,
    nivel_abajo_precio: datosFase.nivel_abajo_precio,
    nivel_abajo_prob_soporte: 100 - abajo_stats.prob,
    nivel_abajo_casos: abajo_stats.casos,
    score_confluencia: datosFase.score_confluencia,
    fase: datosFase.fase,
    updated_at: new Date().toISOString()
  }
}];
